mapper.select:
select ag.Ag_Name as agName, c.C_Name as cName, c.C_Name as cAbbName, mn.* from Oa_Attendance mn left join Sys_Company c on c.C_Id=mn.C_Id left join OA_Attendance_Group ag on ag.Ag_Id=mn.Ag_Id left join Pre_Project pro on pro.P_Id=ag.P_Id where 1=1
and to_char(mn.A_Create_Time, 'yyyy-MM-dd') = substr(#{params.aCreateTime,jdbcType=VARCHAR}, 1, 10)
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.A_Create_Time desc
limit #{params.start},#{params.size}

select ag.Ag_Name as agName, c.C_Name as cName, c.C_Name as cAbbName, mn.* from Oa_Attendance mn left join Sys_Company c on c.C_Id=mn.C_Id left join OA_Attendance_Group ag on ag.Ag_Id=mn.Ag_Id left join Pre_Project pro on pro.P_Id=ag.P_Id where 1=1
and date_format(mn.A_Create_Time,'%Y-%m-%d')= date_format(#{params.aCreateTime},'%Y-%m-%d')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.A_Create_Time desc
limit #{params.start},#{params.size}

select ag.Ag_Name as agName, c.C_Name as cName, c.C_Name as cAbbName, mn.* from Oa_Attendance mn left join Sys_Company c on c.C_Id=mn.C_Id left join OA_Attendance_Group ag on ag.Ag_Id=mn.Ag_Id left join Pre_Project pro on pro.P_Id=ag.P_Id where 1=1
and to_char(mn.A_Create_Time,'yyyy-MM-dd') = to_char(#{params.aCreateTime},'yyyy-MM-dd')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.A_Create_Time desc
limit #{params.start},#{params.size}
